using Godot;
using System;
using System.Collections.Generic;
using GArray=Godot.Collections.Array;
using Settings=Godot.Collections.Dictionary;
public partial class ImageDocumentOperations:RefCounted
{
    private readonly ImageLayerOperations _layers=new();
    private static GArray Layers(Resource owner)=>owner.Get("layers").AsGodotArray();
    private static Dictionary<string,Resource> Index(Resource owner){var index=new Dictionary<string,Resource>(StringComparer.Ordinal);foreach(var raw in Layers(owner)){var layer=raw.As<Resource>();index.TryAdd(layer.Get("id").AsString(),layer);}return index;}
    public Resource? layer_for_id(Resource owner,string id){foreach(var raw in Layers(owner)){var layer=raw.As<Resource>();if(layer.Get("id").AsString()==id)return layer;}return null;}
    public GArray children(Resource owner,string parent){var result=new GArray();foreach(var raw in Layers(owner)){var layer=raw.As<Resource>();if(layer.Get("parent_id").AsString()==parent)result.Add(layer);}return result;}
    private static bool Descendant(Dictionary<string,Resource> index,string id,string ancestor){index.TryGetValue(id,out var layer);var seen=new HashSet<string>(StringComparer.Ordinal);while(layer!=null){string parent=layer.Get("parent_id").AsString();if(parent.Length==0||!seen.Add(layer.Get("id").AsString()))break;if(parent==ancestor)return true;index.TryGetValue(parent,out layer);}return false;}
    public bool is_descendant(Resource owner,string id,string ancestor)=>Descendant(Index(owner),id,ancestor);
    public Transform2D world_transform(Resource owner,Resource layer){var result=_layers.local_transform(layer);var index=Index(owner);index.TryGetValue(layer.Get("parent_id").AsString(),out var current);var seen=new HashSet<string>(StringComparer.Ordinal){layer.Get("id").AsString()};while(current!=null&&seen.Add(current.Get("id").AsString())){result=_layers.local_transform(current)*result;index.TryGetValue(current.Get("parent_id").AsString(),out current);}return result;}
    private static bool IsolationAllows(Resource owner,Resource layer,Dictionary<string,Resource> index){if(layer.Get("isolated").AsBool())return true;bool isolated=false;foreach(var raw in Layers(owner)){var other=raw.As<Resource>();if(!other.Get("isolated").AsBool())continue;isolated=true;if(Descendant(index,layer.Get("id").AsString(),other.Get("id").AsString()))return true;if(layer.Get("kind").AsString()=="group"&&Descendant(index,other.Get("id").AsString(),layer.Get("id").AsString()))return true;}return !isolated;}
    public bool isolation_allows(Resource owner,Resource layer)=>IsolationAllows(owner,layer,Index(owner));
    public bool can_edit(Resource owner,Resource layer){var index=Index(owner);if(!layer.Get("visible").AsBool()||layer.Get("locked").AsBool()||!IsolationAllows(owner,layer,index))return false;index.TryGetValue(layer.Get("parent_id").AsString(),out var parent);var seen=new HashSet<string>(StringComparer.Ordinal){layer.Get("id").AsString()};while(parent!=null){if(!seen.Add(parent.Get("id").AsString())||!parent.Get("visible").AsBool()||parent.Get("locked").AsBool())return false;index.TryGetValue(parent.Get("parent_id").AsString(),out parent);}return true;}
    public GArray selected_roots(Resource owner,GArray ids){var result=new GArray();var index=Index(owner);var selected=new HashSet<string>(StringComparer.Ordinal);foreach(var id in ids)selected.Add(id.AsString());foreach(var raw in Layers(owner)){var layer=raw.As<Resource>();string layerId=layer.Get("id").AsString();if(!selected.Contains(layerId))continue;bool nested=false;foreach(string id in selected)if(Descendant(index,layerId,id)){nested=true;break;}if(!nested)result.Add(layer);}return result;}
    public Resource snapshot(Resource owner)
    {
        var copy=new KiwiImageDocument();foreach(string key in new[]{"version","canvas_size","output_path","preview","active_selection_mask","pixel_selection","pixel_selection_owner","pixel_selection_reference_world","active_live_material_id","live_edit_enabled"})copy.Set(key,owner.Get(key));foreach(string key in new[]{"workspace_state","selection_masks"})copy.Set(key,owner.Get(key).AsGodotDictionary().Duplicate(true));copy.Set("selections",owner.Get("selections").AsGodotDictionary().Duplicate());var reference=owner.Get("pixel_selection_reference").As<Resource>();if(reference!=null)copy.Set("pixel_selection_reference",_layers.copy_layer(reference));using var resources=new ImageMaterialResourceOperations();var materials=copy.Get("live_materials").AsGodotArray();foreach(var template in owner.Get("live_materials").AsGodotArray())materials.Add(resources.copy_template(template.As<Resource>()));var layers=Layers(copy);foreach(var layer in Layers(owner))layers.Add(_layers.copy_layer(layer.As<Resource>()));return copy;
    }
    private static void ResizeText(Resource layer,Vector2 ratio){if(layer.Get("kind").AsString()!="text")return;var properties=layer.Get("properties").AsGodotDictionary();double value=properties.TryGetValue("text_scale",out var scale)?scale.AsDouble():1;properties["text_scale"]=value*Math.Sqrt(Math.Abs(ratio.X*ratio.Y));}
    public void resize_layer(Resource owner,Resource layer,Vector2 dimensions){var ratio=dimensions/layer.Get("dimensions").AsVector2().Max(Vector2.One);ResizeText(layer,ratio);string id=layer.Get("id").AsString();var index=Index(owner);foreach(var raw in Layers(owner)){var child=raw.As<Resource>();if(!Descendant(index,child.Get("id").AsString(),id))continue;child.Set("position",child.Get("position").AsVector2()*ratio);child.Set("dimensions",child.Get("dimensions").AsVector2()*ratio);ResizeText(child,ratio);}layer.Set("dimensions",dimensions);}
    private static string NewId()=>ActorData.new_id();
    private static Resource NewRegion()=>new KiwiLivePaintRegion();
    public Resource create_live_material(Resource owner,Resource material,string label){var template=new KiwiLiveMaterialTemplate();template.Set("id",NewId());using var resources=new ImageMaterialResourceOperations();var instance=resources.copy_material(material);instance.Set("coverage",default(Variant));instance.Set("source",default(Variant));template.Set("material",instance);template.Set("label",label.Trim().Length>0?label:material.Get("label").AsString());owner.Get("live_materials").AsGodotArray().Add(template);owner.Set("active_live_material_id",template.Get("id"));owner.Set("version",Math.Max(owner.Get("version").AsInt64(),2));return template;}
    public Resource? live_material_for_id(Resource owner,string id){foreach(var raw in owner.Get("live_materials").AsGodotArray()){var template=raw.As<Resource>();if(template.Get("id").AsString()==id)return template;}return null;}
    public bool set_live_material(Resource owner,string id,Resource? material){var template=live_material_for_id(owner,id);if(template==null||material==null)return false;using var resources=new ImageMaterialResourceOperations();var copy=resources.copy_material(material);copy.Set("coverage",default(Variant));copy.Set("source",default(Variant));template.Set("material",copy);return true;}
    public bool live_material_has_artwork(Resource owner,string id){foreach(var raw in Layers(owner))foreach(var entry in raw.As<Resource>().Get("live_paint").AsGodotArray()){var region=entry.As<Resource>();var coverage=region.Get("coverage").As<Texture2D>();if(region.Get("template_id").AsString()!=id||coverage==null)continue;using var pixels=coverage.GetImage();if(pixels!=null&&pixels.GetUsedRect().HasArea())return true;}return false;}
    private static Texture2D Blank(Vector2I size){using var image=Image.CreateEmpty(size.X,size.Y,false,Image.Format.Rgba8);image.Fill(Colors.Transparent);return ImageTexture.CreateFromImage(image);}
    public Resource? add_live_region(Resource owner,Resource? layer,string templateId,Texture2D? coverage,Transform2D mapping)
    {
        var template=live_material_for_id(owner,templateId);if(layer==null||template==null)return null;var size=((Vector2I)layer.Get("dimensions").AsVector2().Ceil()).Max(Vector2I.One);bool hasRaster=false;var texture=layer.Get("texture").As<Texture2D>();if(texture!=null){size=(Vector2I)texture.GetSize();using var pixels=texture.GetImage();hasRaster=pixels!=null&&pixels.GetUsedRect().HasArea();}var regions=layer.Get("live_paint").AsGodotArray();if(hasRaster){var frozen=NewRegion();frozen.Set("id",NewId());frozen.Set("raster",texture!);regions.Add(frozen);texture=Blank(size);layer.Set("texture",texture);layer.Set("paint_base",texture);}else if(texture==null){texture=Blank(size);layer.Set("texture",texture);layer.Set("paint_base",texture);}if(coverage==null&&regions.Count>0){var previous=regions[regions.Count-1].As<Resource>();if(previous.Get("template_id").AsString()==templateId&&previous.Get("coordinates").AsGodotObject()==null&&template.Get("material").As<Resource>().Get("application").AsString()=="continuous"&&previous.Get("mapping").AsTransform2D().IsEqualApprox(mapping))return previous;}var region=NewRegion();region.Set("id",NewId());region.Set("template_id",templateId);region.Set("mapping",mapping);region.Set("coverage",coverage??Blank(size));regions.Add(region);owner.Set("version",Math.Max(owner.Get("version").AsInt64(),2));return region;
    }
    public bool delete_live_material(Resource owner,string templateId){var template=live_material_for_id(owner,templateId);if(template==null)return false;foreach(var raw in Layers(owner)){var regions=raw.As<Resource>().Get("live_paint").AsGodotArray();for(int index=regions.Count-1;index>=0;index--)if(regions[index].As<Resource>().Get("template_id").AsString()==templateId)regions.RemoveAt(index);}var materials=owner.Get("live_materials").AsGodotArray();materials.Remove(template);if(owner.Get("active_live_material_id").AsString()==templateId)owner.Set("active_live_material_id",materials.Count>0?materials[0].As<Resource>().Get("id").AsString():"");return true;}
    public void pack_live_material_textures(Resource owner){var packed=new Dictionary<ulong,PortableCompressedTexture2D>();foreach(var raw in Layers(owner))foreach(var item in raw.As<Resource>().Get("live_paint").AsGodotArray()){var region=item.As<Resource>();foreach(string key in new[]{"coverage","raster"}){if(region.Get(key).AsGodotObject() is not ImageTexture texture||texture.ResourcePath.Length>0)continue;ulong id=texture.GetInstanceId();if(!packed.TryGetValue(id,out var compact)){compact=new PortableCompressedTexture2D{KeepCompressedBuffer=true};using var image=texture.GetImage();compact.CreateFromImage(image,PortableCompressedTexture2D.CompressionMode.Lossless);packed[id]=compact;}region.Set(key,compact);}}}
}
